import type { Metadata } from "next";

export const siteUrl =
  process.env.NEXT_PUBLIC_SITE_URL || "https://arshadchowdhury.vercel.app";
export const siteName = "Mohammed Arshad";
export const jobTitle = "Senior Full-Stack Software Engineer";
export const siteTitle = `${siteName} | ${jobTitle}`;
export const siteDescription =
  "Senior Full-Stack Software Engineer building multi-tenant SaaS and payment systems in TypeScript, NestJS, Next.js and PostgreSQL. Open to roles in Germany.";
export const twitterHandle = "@Arshaaaaaaaaaad";

// Generated by app/opengraph-image.tsx and app/twitter-image.tsx (1200x630).
// Pages that define their own `openGraph` must restate these, because the
// file-based image is only merged into the root segment's metadata.
export const socialImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${siteName}, ${jobTitle}`,
};

type PageMetadataInput = {
  title: string;
  description: string;
  path: `/${string}`;
};

// Per-page metadata. Next.js replaces (not merges) nested objects like
// `openGraph`, so each page must restate the shared fields or it inherits the
// home page's title and URL in social previews.
export function pageMetadata({ title, description, path }: PageMetadataInput): Metadata {
  const fullTitle = `${title} | ${siteName}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      url: path,
      siteName,
      locale: "en_US",
      title: fullTitle,
      description,
      images: [socialImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      creator: twitterHandle,
      images: [{ ...socialImage, url: "/twitter-image" }],
    },
  };
}
